<template><view><canvas :id="canvasId" :canvas-id="canvasId" style="position:fixed;left:-12000px;top:0;width:64px;height:64px"/><canvas :id="previewId" :canvas-id="previewId" style="position:fixed;left:-12000px;top:0;width:384px;height:384px"/></view></template>
<script>
import {sealFromPixels,drawPetSeal} from '../common/pet-seal.js';
import {canvasCallback} from '../common/card-renderer.js';
export default{data:()=>({canvasId:'seal_'+Math.random().toString(36).slice(2),previewId:'seal_preview_'+Math.random().toString(36).slice(2)}),methods:{async preview(asset,style,isCurrent,transparent=false){if(!isCurrent())throw Error("SEAL_CONTEXT_CHANGED");const ctx=uni.createCanvasContext(this.previewId,this);ctx.clearRect(0,0,384,384);if(!transparent){ctx.setFillStyle('#FBF8F1');ctx.fillRect(0,0,384,384);}drawPetSeal(ctx,asset,transparent?[0,0,384]:[40,40,304],style);await canvasCallback(resolve=>ctx.draw(false,resolve));if(!isCurrent())throw Error('SEAL_CONTEXT_CHANGED');const file=await canvasCallback((success,fail)=>uni.canvasToTempFilePath({canvasId:this.previewId,x:0,y:0,width:384,height:384,destWidth:384,destHeight:384,fileType:'png',success,fail},this));return file.tempFilePath;},async create(path,sourceKey,isCurrent){const info=await canvasCallback((success,fail)=>uni.getImageInfo({src:path,success,fail}));if(!isCurrent())throw Error('SEAL_CONTEXT_CHANGED');const ctx=uni.createCanvasContext(this.canvasId,this),size=Math.min(info.width,info.height)*.9;ctx.clearRect(0,0,64,64);ctx.drawImage(info.path,(info.width-size)/2,(info.height-size)*.18,size,size,0,0,64,64);await canvasCallback(resolve=>ctx.draw(false,resolve));const result=await canvasCallback((success,fail)=>uni.canvasGetImageData({canvasId:this.canvasId,x:0,y:0,width:64,height:64,success,fail},this));if(!isCurrent())throw Error('SEAL_CONTEXT_CHANGED');return sealFromPixels(result.data,64,64,sourceKey);}}};
</script>